css:
.psychsafety-sim-container {
    padding: 28px;
    background: linear-gradient(135deg, #1a1f3c 0%, #0f1525 50%, #1a0f2e 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e8eaf6;
}

.psychsafety-sim-header {
    text-align: center;
    margin-bottom: 24px;
    padding: 32px;
    background: rgba(255,255,255,0.05);
    border-radius: 20px;
    border: 1px solid rgba(255,255,255,0.1);
}

.psychsafety-sim-header h1 {
    font-size: 2rem;
    font-weight: 700;
    margin: 0 0 8px 0;
    background: linear-gradient(135deg, #a78bfa, #60a5fa);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.psychsafety-sim-header p {
    margin: 0;
    color: #94a3b8;
    font-size: 1.1rem;
}

.psychsafety-sim-context-bar {
    display: flex;
    justify-content: center;
    gap: 32px;
    margin-bottom: 24px;
    flex-wrap: wrap;
}

.psychsafety-sim-context-item {
    text-align: center;
    padding: 16px 24px;
    background: rgba(255,255,255,0.05);
    border-radius: 12px;
    border: 1px solid rgba(255,255,255,0.08);
}

.psychsafety-sim-context-label {
    display: block;
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #64748b;
    margin-bottom: 4px;
}

.psychsafety-sim-context-value {
    font-size: 1rem;
    font-weight: 600;
    color: #cbd5e1;
}

.psychsafety-sim-period-counter {
    text-align: center;
    font-size: 1.3rem;
    color: #94a3b8;
    margin-bottom: 24px;
    padding: 12px;
    background: rgba(167,139,250,0.1);
    border-radius: 8px;
    border: 1px solid rgba(167,139,250,0.2);
}

.psychsafety-sim-period-counter span:nth-child(2),
.psychsafety-sim-period-counter span:nth-child(4) {
    font-weight: 700;
    color: #a78bfa;
    font-size: 1.5rem;
}

.psychsafety-sim-dashboard {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 16px;
    margin-bottom: 28px;
}

.psychsafety-sim-kpi-card {
    background: rgba(255,255,255,0.07);
    backdrop-filter: blur(12px);
    border: 1px solid rgba(255,255,255,0.12);
    border-radius: 16px;
    padding: 20px;
    text-align: center;
    transition: all 0.3s ease;
}

.psychsafety-sim-kpi-card:hover {
    transform: translateY(-4px);
    background: rgba(255,255,255,0.1);
}

.psychsafety-sim-kpi-label {
    font-size: 0.75rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: #94a3b8;
    margin-bottom: 8px;
}

.psychsafety-sim-kpi-value {
    font-size: 2rem;
    font-weight: 700;
    color: #e8eaf6;
    margin-bottom: 8px;
}

.psychsafety-sim-kpi-sublabel {
    font-size: 0.8rem;
    color: #64748b;
}

.psychsafety-sim-kpi-bar {
    height: 6px;
    background: rgba(255,255,255,0.1);
    border-radius: 3px;
    overflow: hidden;
}

.psychsafety-sim-kpi-fill {
    height: 100%;
    background: linear-gradient(90deg, #a78bfa, #60a5fa);
    border-radius: 3px;
    transition: width 0.5s ease;
}

#safetyCard .psychsafety-sim-kpi-fill { background: linear-gradient(90deg, #f472b6, #a78bfa); }
#trustCard .psychsafety-sim-kpi-fill { background: linear-gradient(90deg, #34d399, #60a5fa); }
#innovationCard .psychsafety-sim-kpi-fill { background: linear-gradient(90deg, #fbbf24, #f472b6); }
#launchCard .psychsafety-sim-kpi-fill { background: linear-gradient(90deg, #60a5fa, #34d399); }

.psychsafety-sim-scenario-panel {
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 16px;
    padding: 24px;
    margin-bottom: 24px;
}

.psychsafety-sim-scenario-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 16px;
}

.psychsafety-sim-meeting-badge {
    background: linear-gradient(135deg, #a78bfa, #60a5fa);
    color: white;
    padding: 6px 14px;
    border-radius: 20px;
    font-size: 0.8rem;
    font-weight: 600;
    text-transform: uppercase;
}

.psychsafety-sim-scenario-header h3 {
    margin: 0;
    font-size: 1.3rem;
    color: #e8eaf6;
}

.psychsafety-sim-scenario-text {
    font-size: 1.05rem;
    line-height: 1.7;
    color: #cbd5e1;
    margin-bottom: 16px;
}

.psychsafety-sim-character-tags {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
}

.psychsafety-sim-tag {
    background: rgba(167,139,250,0.15);
    color: #c4b5fd;
    padding: 4px 12px;
    border-radius: 12px;
    font-size: 0.8rem;
    border: 1px solid rgba(167,139,250,0.3);
}

.psychsafety-sim-decision-panel {
    background: rgba(255,255,255,0.07);
    border: 1px solid rgba(255,255,255,0.15);
    border-radius: 20px;
    padding: 28px;
    margin-bottom: 24px;
}

.psychsafety-sim-decision-panel h3 {
    margin: 0 0 16px 0;
    font-size: 1.2rem;
    color: #a78bfa;
}

.psychsafety-sim-decision-context {
    font-size: 1.1rem;
    color: #e8eaf6;
    margin-bottom: 20px;
    padding: 16px;
    background: rgba(0,0,0,0.2);
    border-radius: 12px;
    border-left: 4px solid #a78bfa;
}

.psychsafety-sim-options {
    display: flex;
    flex-direction: column;
    gap: 12px;
    margin-bottom: 20px;
}

.psychsafety-sim-option-btn {
    display: flex;
    align-items: flex-start;
    gap: 16px;
    padding: 16px 20px;
    background: rgba(255,255,255,0.05);
    border: 2px solid rgba(255,255,255,0.1);
    border-radius: 12px;
    cursor: pointer;
    transition: all 0.2s ease;
    text-align: left;
    color: #e8eaf6;
}

.psychsafety-sim-option-btn:hover {
    background: rgba(167,139,250,0.1);
    border-color: rgba(167,139,250,0.4);
}

.psychsafety-sim-option-btn.selected {
    background: rgba(167,139,250,0.2);
    border-color: #a78bfa;
}

.psychsafety-sim-option-label {
    background: rgba(167,139,250,0.2);
    color: #c4b5fd;
    padding: 4px 10px;
    border-radius: 6px;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    white-space: nowrap;
}

.psychsafety-sim-option-text {
    font-size: 1rem;
    line-height: 1.5;
    color: #e8eaf6;
}

.psychsafety-sim-submit-btn {
    width: 100%;
    padding: 16px;
    background: linear-gradient(135deg, #a78bfa, #60a5fa);
    color: white;
    border: none;
    border-radius: 12px;
    font-size: 1.1rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s ease;
}

.psychsafety-sim-submit-btn:hover:not(:disabled) {
    transform: translateY(-2px);
    box-shadow: 0 8px 24px rgba(167,139,250,0.3);
}

.psychsafety-sim-submit-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

.psychsafety-sim-feedback-panel {
    background: rgba(52,211,153,0.1);
    border: 1px solid rgba(52,211,153,0.3);
    border-radius: 16px;
    padding: 24px;
    margin-bottom: 24px;
    animation: slideIn 0.3s ease;
}

@keyframes slideIn {
    from { opacity: 0; transform: translateY(-10px); }
    to { opacity: 1; transform: translateY(0); }
}

.psychsafety-sim-feedback-header {
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #34d399;
    margin-bottom: 12px;
    font-weight: 600;
}

.psychsafety-sim-feedback-text {
    font-size: 1.05rem;
    line-height: 1.7;
    color: #e8eaf6;
    margin-bottom: 16px;
}

.psychsafety-sim-impact-summary {
    display: flex;
    gap: 16px;
    flex-wrap: wrap;
}

.psychsafety-sim-impact-item {
    background: rgba(0,0,0,0.2);
    padding: 8px 16px;
    border-radius: 8px;
    font-size: 0.9rem;
}

.psychsafety-sim-impact-item.positive { color: #34d399; }
.psychsafety-sim-impact-item.negative { color: #f87171; }
.psychsafety-sim-impact-item.neutral { color: #94a3b8; }

.psychsafety-sim-team-status {
    background: rgba(255,255,255,0.05);
    border: 1px solid rgba(255,255,255,0.1);
    border-radius: 16px;
    padding: 24px;
    margin-bottom: 24px;
}

.psychsafety-sim-team-status h4 {
    margin: 0 0 16px 0;
    font-size: 1.1rem;
    color: #94a3b8;
}

.psychsafety-sim-team-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(140px, 1fr));
    gap: 12px;
}

.psychsafety-sim-member {
    background: rgba(255,255,255,0.05);
    border-radius: 12px;
    padding: 16px;
    text-align: center;
    border: 1px solid rgba(255,255,255,0.08);
    transition: all 0.2s ease;
}

.psychsafety-sim-member-name {
    font-weight: 600;
    color: #e8eaf6;
    margin-bottom: 4px;
}

.psychsafety-sim-member-role {
    font-size: 0.75rem;
    color: #64748b;
    margin-bottom: 8px;
}

.psychsafety-sim-member-state {
    font-size: 0.8rem;
    padding: 4px 10px;
    border-radius: 12px;
    font-weight: 500;
    display: inline-block;
}

.psychsafety-sim-member-state[data-state="guarded"] { background: rgba(248,113,113,0.2); color: #f87171; }
.psychsafety-sim-member-state[data-state="engaged"] { background: rgba(52,211,153,0.2); color: #34d399; }
.psychsafety-sim-member-state[data-state="defensive"] { background: rgba(251,191,36,0.2); color: #fbbf24; }
.psychsafety-sim-member-state[data-state="open"] { background: rgba(96,165,250,0.2); color: #60a5fa; }
.psychsafety-sim-member-state[data-state="anxious"] { background: rgba(167,139,250,0.2); color: #c4b5fd; }
.psychsafety-sim-member-state[data-state="confident"] { background: rgba(52,211,153,0.2); color: #34d399; }
.psychsafety-sim-member-state[data-state="invisible"] { background: rgba(100,116,139,0.2); color: #94a3b8; }
.psychsafety-sim-member-state[data-state="contributing"] { background: rgba(52,211,153,0.2); color: #34d399; }
.psychsafety-sim-member-state[data-state="ignored"] { background: rgba(248,113,113,0.2); color: #f87171; }
.psychsafety-sim-member-state[data-state="heard"] { background: rgba(96,165,250,0.2); color: #60a5fa; }
.psychsafety-sim-member-state[data-state="compliant"] { background: rgba(251,191,36,0.2); color: #fbbf24; }
.psychsafety-sim-member-state[data-state="candid"] { background: rgba(52,211,153,0.2); color: #34d399; }
.psychsafety-sim-member-state[data-state="withdrawing"] { background: rgba(248,113,113,0.2); color: #f87171; }
.psychsafety-sim-member-state[data-state="committed"] { background: rgba(52,211,153,0.2); color: #34d399; }
.psychsafety-sim-member-state[data-state="disengaged"] { background: rgba(100,116,139,0.2); color: #64748b; }
.psychsafety-sim-member-state[data-state="re-engaged"] { background: rgba(96,165,250,0.2); color: #60a5fa; }

.psychsafety-sim-chart {
    height: 300px;
    margin-bottom: 24px;
    background: rgba(255,255,255,0.05);
    border-radius: 16px;
    padding: 20px;
}

.psychsafety-sim-history {
    margin-bottom: 24px;
}

.psychsafety-sim-final-panel {
    background: rgba(255,255,255,0.07);
    border: 2px solid rgba(167,139,250,0.3);
    border-radius: 20px;
    padding: 32px;
    text-align: center;
}

.psychsafety-sim-final-panel h2 {
    margin: 0 0 24px 0;
    font-size: 1.8rem;
    background: linear-gradient(135deg, #a78bfa, #60a5fa);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.psychsafety-sim-archetype {
    font-size: 1.5rem;
    font-weight: 700;
    color: #e8eaf6;
    margin-bottom: 24px;
    padding: 20px;
    background: rgba(0,0,0,0.2);
    border-radius: 12px;
}

.psychsafety-sim-final-metrics {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}

.psychsafety-sim-final-metric {
    background: rgba(255,255,255,0.05);
    padding: 16px;
    border-radius: 12px;
}

.psychsafety-sim-final-metric-label {
    font-size: 0.8rem;
    color: #94a3b8;
    text-transform: uppercase;
    margin-bottom: 8px;
}

.psychsafety-sim-final-metric-value {
    font-size: 1.5rem;
    font-weight: 700;
    color: #e8eaf6;
}

.psychsafety-sim-team-outcomes {
    text-align: left;
    background: rgba(0,0,0,0.2);
    border-radius: 12px;
    padding: 20px;
}

.psychsafety-sim-team-outcome {
    padding: 12px;
    border-bottom: 1px solid rgba(255,255,255,0.1);
}

.psychsafety-sim-team-outcome:last-child {
    border-bottom: none;
}

.psychsafety-sim-team-outcome-name {
    font-weight: 600;
    color: #a78bfa;
    margin-bottom: 4px;
}

.psychsafety-sim-team-outcome-text {
    font-size: 0.95rem;
    color: #cbd5e1;
    line-height: 1.5;
}

@media (max-width: 768px) {
    .psychsafety-sim-container {
        padding: 16px;
    }

    .psychsafety-sim-header {
        padding: 20px;
    }

    .psychsafety-sim-header h1 {
        font-size: 1.5rem;
    }

    .psychsafety-sim-context-bar {
        gap: 12px;
    }

    .psychsafety-sim-dashboard {
        grid-template-columns: repeat(2, 1fr);
    }

    .psychsafety-sim-kpi-value {
        font-size: 1.5rem;
    }

    .psychsafety-sim-team-grid {
        grid-template-columns: repeat(2, 1fr);
    }

    .psychsafety-sim-option-btn {
        flex-direction: column;
        gap: 8px;
    }
}

